package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.DurationFieldType;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MutableDateTime_add_TriageGen1Test {

    @Test(expected = IllegalArgumentException.class)
    public void testAdd_NullType_ThrowsException() {
        MutableDateTime dt = new MutableDateTime();
        dt.add(null, 1);
    }

    @Test
    public void testAdd_Years() {
        // Set to 2020-01-01
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.add(DurationFieldType.year(), 2);
        assertEquals(2022, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAdd_Months() {
        // Set to 2020-01-01
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.add(DurationFieldType.monthOfYear(), 3);
        assertEquals(2020, dt.getYear());
        assertEquals(4, dt.getMonthOfYear());
    }

    @Test
    public void testAdd_Days() {
        // Set to 2020-01-01
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.add(DurationFieldType.dayOfMonth(), 10);
        assertEquals(11, dt.getDayOfMonth());
    }

    @Test
    public void testAdd_Hours() {
        // Set to 10:00:00
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 0, 0, 0);
        dt.add(DurationFieldType.hourOfDay(), 5);
        assertEquals(15, dt.getHourOfDay());
    }

    @Test
    public void testAdd_Minutes() {
        // Set to 10:00:00
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 0, 0, 0);
        dt.add(DurationFieldType.minuteOfHour(), 30);
        assertEquals(30, dt.getMinuteOfHour());
    }

    @Test
    public void testAdd_Seconds() {
        // Set to 10:00:00
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 0, 0, 0);
        dt.add(DurationFieldType.secondOfMinute(), 45);
        assertEquals(45, dt.getSecondOfMinute());
    }

    @Test
    public void testAdd_Millis() {
        // Set to 10:00:00.000
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 0, 0, 0);
        dt.add(DurationFieldType.millisOfSecond(), 500);
        assertEquals(500, dt.getMillisOfSecond());
    }

    @Test
    public void testAdd_NegativeAmount() {
        // Set to 2020-01-10
        MutableDateTime dt = new MutableDateTime(2020, 1, 10, 0, 0, 0, 0);
        dt.add(DurationFieldType.dayOfMonth(), -5);
        assertEquals(5, dt.getDayOfMonth());
    }

    @Test
    public void testAdd_OverflowYear() {
        // Set to 2020-12-01
        MutableDateTime dt = new MutableDateTime(2020, 12, 1, 0, 0, 0, 0);
        dt.add(DurationFieldType.monthOfYear(), 2);
        assertEquals(2021, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
    }
}
